"""Verify copied/generated bytes without requiring the original Windows machine."""
import argparse
import gzip
import hashlib
import json
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parents[1]


def digest(path):
    result = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024*1024), b''):
            result.update(chunk)
    return result.hexdigest()


def verify_rows(rows):
    failures, seen = [], set()
    for row in rows:
        relative = PurePosixPath(row['path'])
        if relative.is_absolute() or '..' in relative.parts or row['path'] in seen:
            failures.append({'path': row['path'], 'reason': 'unsafe or duplicate manifest path'})
            continue
        seen.add(row['path'])
        path = ROOT / row['path']
        if not path.is_file() or path.is_symlink() or ROOT not in path.resolve().parents:
            failures.append({'path': row['path'], 'reason': 'missing or unsafe file'})
        elif digest(path) != row['sha256']:
            failures.append({'path': row['path'], 'reason': 'SHA-256 differs'})
    return failures


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path)
    args = parser.parse_args()
    rows = json.loads((ROOT / 'TRANSFER/source-files.json').read_text(encoding='utf-8'))
    generated_path = ROOT / 'TRANSFER/transfer-files.json'
    if not generated_path.is_file():
        raise SystemExit('Missing required transfer-files.json manifest')
    generated = json.loads(generated_path.read_text(encoding='utf-8'))
    if not rows or not generated:
        raise SystemExit('Source and transfer manifests must both be nonempty')
    failures = verify_rows(rows) + verify_rows(generated)
    archive = ROOT / 'TRANSFER/historical-migration-manifest.jsonl.gz'
    with gzip.open(archive, 'rt', encoding='utf-8') as stream:
        historical_rows = sum(1 for line in stream if line.strip())
    scan = json.loads((ROOT / 'TRANSFER/secret-scan.json').read_text(encoding='utf-8'))
    if scan['findings']:
        failures.append({'reason': 'Secret scanner candidates unresolved'})
    if scan['files_scanned'] != len(rows):
        failures.append({'reason': 'Secret scan does not cover the copied-source inventory'})
    result = {'source_files_verified': len(rows), 'transfer_files_verified': len(generated),
              'historical_inventory_rows_read': historical_rows, 'secret_scan_candidates': len(scan['findings']),
              'failures': failures, 'scope': 'Exact transfer-byte integrity; not historical external-link, runtime, model or hardware qualification'}
    text = json.dumps(result, indent=2)
    print(text)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text+'\n', encoding='utf-8')
    if failures:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
